syntax:
for (int i = 1; i <= 20; i++) {
    if (i % 7 == 0) {
        break;       // leave the whole loop now
    }
    if (i % 2 == 0) {
        continue;    // skip the rest of THIS turn, go to i++
    }
    cout << i << " ";   // reached only if no break/continue happened
}
// after break, the program continues HERE

switch (choice) {
    case 1: cout << "One"; break;   // break leaves the switch only
    default: cout << "Other";
}

sample.code:
#include <iostream>
using namespace std;

int main() {
    for (int i = 1; i <= 20; i++) {
        if (i % 7 == 0) {
            cout << "\nFound: " << i << endl;
            break;
        }
        cout << i << " ";
    }
    cout << "Done" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int sum = 0;
    for (int i = 1; i <= 10; i++) {
        if (i % 3 == 0) {
            continue;
        }
        cout << i << " ";
        sum += i;
    }
    cout << endl;
    cout << "Sum: " << sum << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    for (int i = 1; i <= 3; i++) {
        for (int j = 1; j <= 3; j++) {
            if (j == 2) {
                break;
            }
            cout << i << "," << j << " ";
        }
        cout << "| ";
    }
    cout << endl;
    return 0;
}

