int i = 0;
while (i < 5) {
    if (i == 2) {
        i++;
        continue;
    }
    cout << i << " ";
    i++;
}

#include <iostream>
using namespace std;
int main() {
    int n;
    bool isPrime = true;
    cin >> n;
    if (n < 2) {
        isPrime = false;
    }
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            isPrime = false;
            break;
        }
    }
    cout << n << (isPrime ? " is prime" : " is not prime") << endl;
    return 0;
}
